CREATE TABLE principals(id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), repository text NOT NULL UNIQUE CHECK(length(repository) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agents(id text PRIMARY KEY);
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, agent_id text NOT NULL REFERENCES agents, principal_id text NOT NULL REFERENCES principals, branch text NOT NULL, git_revision text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, revision integer NOT NULL DEFAULT 1, UNIQUE(project_id,id));
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 500), state text NOT NULL DEFAULT 'planned' CHECK(state IN ('planned','active','blocked','implemented','committed','tested','verified','released')), revision integer NOT NULL DEFAULT 1 CHECK(revision>0), git_revision text NOT NULL DEFAULT '', claimed_by text REFERENCES principals, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,id));
CREATE TABLE task_dependencies(project_id uuid NOT NULL, task_id uuid NOT NULL, depends_on uuid NOT NULL, PRIMARY KEY(project_id,task_id,depends_on), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,depends_on) REFERENCES tasks(project_id,id), CHECK(task_id<>depends_on));
CREATE TABLE evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, task_id uuid, source_kind text NOT NULL CHECK(source_kind IN ('git_commit','pull_request','build','test','ci','log','human','inference','release')), locator text NOT NULL CHECK(length(locator) BETWEEN 1 AND 2000), git_revision text NOT NULL, artifact_digest text NOT NULL DEFAULT '', outcome text NOT NULL CHECK(outcome IN ('pass','fail','unknown')), summary text NOT NULL CHECK(length(summary) BETWEEN 1 AND 8000), reported_by text NOT NULL REFERENCES principals, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id));
CREATE TABLE attestations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, evidence_id uuid NOT NULL, principal_id text NOT NULL REFERENCES principals, statement text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,evidence_id) REFERENCES evidence(project_id,id), UNIQUE(evidence_id));
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, task_id uuid, session_id uuid, kind text NOT NULL, body text NOT NULL CHECK(length(body) BETWEEN 1 AND 8000), principal_id text NOT NULL REFERENCES principals, agent_id text NOT NULL DEFAULT '', git_revision text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id));
CREATE TABLE records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, task_id uuid, session_id uuid, kind text NOT NULL CHECK(kind IN ('decision','issue','observation','handoff')), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 500), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 8000), git_revision text NOT NULL DEFAULT '', principal_id text NOT NULL REFERENCES principals, agent_id text NOT NULL DEFAULT '', evidence_id uuid, supersedes uuid, created_at timestamptz NOT NULL DEFAULT now(), search_vector tsvector GENERATED ALWAYS AS (to_tsvector('english',title || ' ' || body)) STORED, UNIQUE(project_id,id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES sessions(project_id,id), FOREIGN KEY(project_id,evidence_id) REFERENCES evidence(project_id,id), FOREIGN KEY(project_id,supersedes) REFERENCES records(project_id,id), UNIQUE(supersedes));
CREATE TABLE operations(project_id uuid NOT NULL REFERENCES projects, operation_id text NOT NULL CHECK(length(operation_id) BETWEEN 8 AND 100), principal_id text NOT NULL REFERENCES principals, payload_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,principal_id,operation_id));
CREATE INDEX records_search ON records USING gin(search_vector);
CREATE INDEX records_project_time ON records(project_id,created_at DESC,id);
CREATE INDEX events_project_time ON events(project_id,created_at DESC,id);
CREATE INDEX tasks_project_state ON tasks(project_id,state,updated_at DESC);
CREATE INDEX evidence_task_revision ON evidence(project_id,task_id,git_revision);
CREATE INDEX sessions_project_time ON sessions(project_id,started_at DESC);
CREATE FUNCTION reject_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'history is append-only'; END $$;
CREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON events FOR EACH ROW EXECUTE FUNCTION reject_history_change();
CREATE TRIGGER immutable_records BEFORE UPDATE OR DELETE ON records FOR EACH ROW EXECUTE FUNCTION reject_history_change();
CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON evidence FOR EACH ROW EXECUTE FUNCTION reject_history_change();
CREATE TRIGGER immutable_attestations BEFORE UPDATE OR DELETE ON attestations FOR EACH ROW EXECUTE FUNCTION reject_history_change();
CREATE TRIGGER immutable_operations BEFORE UPDATE OR DELETE ON operations FOR EACH ROW EXECUTE FUNCTION reject_history_change();
